"""Render the hostapd, dnsmasq and nftables configuration files.

Rendering is a pure function of the validated configuration, which makes it
testable and lets the CLI validate everything before touching the live system.
"""

from __future__ import annotations

import ipaddress
from typing import Any

from . import paths, util
from .errors import ConfigurationError

HEADER = (
    "# ------------------------------------------------------------------\n"
    "# Generated by XPDevs NetworkOS {version}. Do not edit by hand:\n"
    "# changes are overwritten whenever the network configuration is applied.\n"
    "# Manage settings in the dashboard or with: networkosctl\n"
    "# ------------------------------------------------------------------\n"
)


def _header(version: str) -> str:
    return HEADER.format(version=version)


def _quote_ssid(ssid: str) -> str:
    return '"' + ssid.replace("\\", "\\\\").replace('"', '\\"') + '"'


def render_hostapd(cfg, version: str) -> str:
    wifi = cfg.wifi
    if not wifi.psk or len(wifi.psk) != 64:
        raise ConfigurationError("The Wi-Fi pre-shared key is missing. Set the Wi-Fi password again.")
    try:
        int(wifi.psk, 16)
    except ValueError:
        raise ConfigurationError("The stored Wi-Fi pre-shared key is not valid.")

    lines = [
        _header(version),
        f"interface={cfg.network.lan_interface}",
        "driver=nl80211",
        "ctrl_interface=/run/xpdevs-hostapd",
        "ctrl_interface_group=0",
        f"ssid={_quote_ssid(wifi.ssid)}",
        f"hw_mode={wifi.hw_mode}",
        f"channel={wifi.channel}",
        "ieee80211n=1" if wifi.ieee80211n else "ieee80211n=0",
        "wmm_enabled=1",
        "auth_algs=1",
        "macaddr_acl=0",
        f"ignore_broadcast_ssid={1 if wifi.hidden else 0}",
        "wpa=2",
        "wpa_key_mgmt=WPA-PSK",
        "rsn_pairwise=CCMP",
        f"wpa_psk={wifi.psk}",
        "ap_isolate=1" if wifi.isolate_clients else "ap_isolate=0",
        f"max_num_sta={max(1, min(int(wifi.max_clients), 200))}",
        "beacon_int=100",
        "dtim_period=2",
        "logger_syslog=-1",
        "logger_syslog_level=2",
        "logger_stdout=-1",
        "logger_stdout_level=0",
        "dump_file=/tmp/xpdevs-hostapd.dump",
    ]
    if wifi.country:
        lines.append(f"country_code={wifi.country.upper()}")
        lines.append("ieee80211d=1")
    return "\n".join(lines) + "\n"


def render_dnsmasq(cfg, version: str) -> str:
    net = cfg.network
    dns_servers = ",".join(net.dns_servers) if net.dns_servers else net.lan_address
    lines = [
        _header(version),
        "# DHCP only: port 0 disables dnsmasq's own resolver so that every",
        "# client query is answered (and logged) by Pi-hole.",
        "port=0",
        f"interface={net.lan_interface}",
        "bind-dynamic",
        f"except-interface={net.wan_interface}",
        f"dhcp-range={net.dhcp_start},{net.dhcp_end},255.255.255.0,{net.lease_time}",
        "dhcp-authoritative",
        f"dhcp-option=option:router,{net.lan_address}",
        f"dhcp-option=option:dns-server,{dns_servers}",
        f"dhcp-option=option:domain-name,{net.domain}",
        "dhcp-option=option:netmask,255.255.255.0",
        f"domain={net.domain}",
        "local-service",
        "no-resolv",
        "no-hosts",
        f"dhcp-leasefile={paths.DHCP_LEASES}",
        "dhcp-lease-max=250",
        "quiet-dhcp",
        "log-facility=-",
        "pid-file=/run/xpdevs-dnsmasq.pid",
    ]
    return "\n".join(lines) + "\n"


def render_nftables(cfg, version: str) -> str:
    net = cfg.network
    lan = net.lan_interface
    wan = net.wan_interface
    prefix = int(net.lan_prefix)
    network = ipaddress.IPv4Network(f"{net.lan_address}/{prefix}", strict=False)
    lan_cidr = str(network)
    admin_ports = "{ 80, 443 }"
    ssh_rule = [f"        iifname {{ {lan}, {wan} }} tcp dport 22 accept"] if net.wan_ssh else [
        f"        iifname {lan} tcp dport 22 accept"
    ]

    lines: list[str] = [
        _header(version),
        "table inet networkos {",
        "    set blocked_macs {",
        "        type ether_addr",
        "    }",
        "",
        "    chain input {",
        "        type filter hook input priority filter; policy drop;",
        "        iif lo accept",
        "        ct state established,related accept",
        "        ct state invalid drop",
        "        ether saddr @blocked_macs drop",
        "        ip protocol icmp accept",
        "        ip6 nexthdr ipv6-icmp accept",
        f"        iifname {wan} udp dport 68 accept",
        f"        iifname {lan} udp dport 67 accept",
        f"        iifname {lan} udp dport 53 accept",
        f"        iifname {lan} tcp dport 53 accept",
        f"        iifname {{ {lan}, {wan} }} tcp dport {admin_ports} accept",
        f"        ip saddr {lan_cidr} tcp dport {admin_ports} accept",
        *ssh_rule,
        "        counter comment \"input denied\"",
        "    }",
        "",
        "    chain forward {",
        "        type filter hook forward priority filter; policy drop;",
        "        ct state established,related accept",
        "        ether saddr @blocked_macs drop",
        "        ether daddr @blocked_macs drop",
        f"        iifname {lan} oifname {wan} counter accept",
        "    }",
        "",
        "    chain output {",
        "        type filter hook output priority filter; policy accept;",
        "    }",
    ]
    if net.nat_enabled:
        lines += [
            "",
            "    chain prerouting {",
            "        type nat hook prerouting priority dstnat; policy accept;",
            f"        iifname {lan} udp dport 53 redirect to :53",
            f"        iifname {lan} tcp dport 53 redirect to :53",
            "    }",
            "",
            "    chain postrouting {",
            "        type nat hook postrouting priority srcnat; policy accept;",
            f"        oifname {wan} ip saddr {lan_cidr} masquerade",
            "    }",
        ]
    lines.append("}")
    return "\n".join(lines) + "\n"


def render_sysctl(cfg, version: str) -> str:
    lines = [
        _header(version),
        "net.ipv4.ip_forward = 1" if cfg.network.nat_enabled else "net.ipv4.ip_forward = 0",
        "net.ipv4.conf.all.forwarding = 1" if cfg.network.nat_enabled else "net.ipv4.conf.all.forwarding = 0",
        "net.ipv6.conf.all.forwarding = 0",
        f"net.ipv4.conf.{cfg.network.lan_interface}.forwarding = 1",
        f"net.ipv4.conf.{cfg.network.wan_interface}.forwarding = 1",
        "net.ipv4.conf.all.rp_filter = 2",
        "net.ipv4.icmp_echo_ignore_broadcasts = 1",
        "net.ipv4.conf.all.accept_redirects = 0",
        "net.ipv4.conf.all.send_redirects = 0",
        "net.ipv4.conf.all.accept_source_route = 0",
        f"net.ipv4.conf.{cfg.network.lan_interface}.send_redirects = 0",
        f"net.ipv4.conf.{cfg.network.wan_interface}.send_redirects = 0",
    ]
    return "\n".join(lines) + "\n"


def render_dhcp_hosts(cfg, devices: list[dict[str, Any]], version: str) -> str:
    """Optional static reservations collected from the device table."""
    lines = [_header(version)]
    for device in devices:
        mac = util.normalize_mac(device.get("mac"))
        ip = util.valid_ipv4(device.get("ip"))
        if not mac or not ip:
            continue
        lines.append(f"dhcp-host={mac},{ip}")
    return "\n".join(lines) + "\n"


def render_all(cfg, version: str) -> dict[str, str]:
    return {
        "hostapd": render_hostapd(cfg, version),
        "dnsmasq": render_dnsmasq(cfg, version),
        "nft": render_nftables(cfg, version),
        "sysctl": render_sysctl(cfg, version),
    }
